                float avgILvl = caster->ToPlayer()->GetAverageItemLevelTotal();
                if (avgILvl < baseItemLevel)
                    return;                     // TODO: Research possibility of scaling down

                amount = uint16((avgILvl - baseItemLevel) * factor);
            }

