        if (Unit* caster = GetCaster())
        {
            if (Unit* target = GetHitUnit())
            {
                float bp0 = GetHitHeal() / 20.f;
                float bp1 = GetHitHeal() / 2.f;

                if (caster->HasAura(81749) && !caster->HasAura(214205))
                    caster->CastSpell(target, 194384, true);

